    }

    function testRegression_property() public {
        // Fund the contract via the attacker (so contract has balance)
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "funding failed");

        // Attacker attempts to withdraw all (should only be allowed for owner in reference)
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference version, this call reverts (onlyOwner modifier catches non-owner)
        // In buggy version, this call succeeds and transfers balance to attacker
        // So assert that the call reverted (ok == false) for reference; for buggy, it will be true, causing assertion failure.
        assertTrue(!ok);

        // Additionally, check that owner's balance is still intact (attacker didn't steal)
        // But the single assertion is enough; we just need to ensure the test fails on buggy.
        // The above assertion diverges: reference passes (!ok == true), buggy fails (!ok == false).
    }
}

