    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: non-owner sends 1 ether via fallback
        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool okFallback, ) = address(c).call{value: 1 ether}("");
        require(okFallback, "fallback failed");

        // Owner attempts to withdraw all
        address owner = c.owner();
        uint256 balanceBeforeOwner = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(owner);
        c.withdrawAll();

        // Assert: reference contract sends balance to owner; modified doesn't
        assertEq(address(c).balance, 0);
    }
}
